INSERT INTO public.culture_stories VALUES (2, 7, 'Kiribath', 'https://www.peckishme.com/wp-content/uploads/2017/03/milk-rice1.jpg', 'Sri Lanka', 'A traditional Sri Lankan dish made with rice cooked in coconut milk, often served at special occasions.', 'Kiribath, a traditional Sri Lankan milk rice dish, holds deep cultural significance as a symbol of unity and prosperity. It is a staple during the Sinhala and Tamil New Year (Aluth Avurudu) in April, where families gather to share this creamy, spiced rice cooked in milk. A fun fact is that Kiribath is often served with sweetmeats like kavum, enhancing its festive appeal.');
INSERT INTO public.culture_stories VALUES (11, 16, 'Hangi', 'https://theaussiebutcher.com/wp-content/uploads/2025/02/shutterstock_633973829-scaled.jpg', 'New Zealand', 'A traditional Māori cooking method from New Zealand, where food is steamed in an earth oven using hot stones', 'Hangi, a traditional Māori earth oven, is a cherished symbol of community and togetherness in New Zealand. It''s often served at significant gatherings like weddings and cultural festivals, such as Matariki, the Māori New Year, which celebrates renewal and heritage. A fun fact: Hangi involves slow-cooking food wrapped in leaves over heated stones for hours, infusing it with a unique, smoky flavor. This labor-intensive process reflects the care and unity it embodies.');
INSERT INTO public.culture_stories VALUES (12, 17, 'Kumara', ',https://www.yates.co.nz/media/q5ppmvc5/red-kumara.jpg?rmode=max&ranchor=center&quality=100&width=638&height=626', 'New Zealand', 'A type of sweet potato deeply rooted in New Zealand''s culture and cuisine, used in various dishes.', 'Kumara, or sweet potato, holds deep cultural significance for the Māori people of New Zealand, being a staple crop brought by their ancestors from Hawaiki. It symbolizes sustenance, spirituality, and connection to the land. Kumara is celebrated during planting and harvesting ceremonies, which involve rituals to ensure a bountiful yield. Interestingly, Kumara varieties come in vibrant colors like purple, red, and white, adding a colorful twist to its rich history.');
INSERT INTO public.culture_stories VALUES (7, 12, 'Dimsum', 'https://www.unileverfoodsolutions.co.id/dam/global-ufs/mcos/SEA/calcmenu/recipes/ID-recipes/chicken-&-other-poultry-dishes/prawn---chicken-shumai-dimsum/Dimsum1260-700.jpg', 'China', 'a traditional Cantonese dish of steamed dumplings and other small bites, typically served in bamboo baskets as part of a social yum cha meal.', 'Dim sum, a Cantonese tradition, embodies the spirit of communal dining, where families and friends gather to share a variety of small, delicate dishes, often accompanied by tea. This practice, known as "yum cha," highlights the importance of social bonding and conversation. Dim sum is notably associated with the Dragon Boat Festival, where zongzi, glutinous rice dumplings, are a cherished tradition. The term "dim sum" itself translates to "touch the heart," reflecting the delightful and varied flavors designed to please the palate.');
INSERT INTO public.culture_stories VALUES (4, 9, 'Hoppers', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR32nDgh57wrLektK5WcH8dU3ZFyVGcC9hRFg&s', 'Sri Lanka', 'A South Asian fermented rice and coconut milk pancake with crispy edges and a soft center, typically enjoyed with sweet or savory accompaniments.', 'Hoppers, a beloved Sri Lankan breakfast staple, are thin, crispy, and bowl-shaped pancakes made from fermented rice flour batter. They hold cultural significance as a comfort food, often enjoyed with dhal, sambal, or sweet fillings like honey. A fun fact is the batter''s fermentation, which gives hoppers their sourdough flavor, and they''re cooked in a unique wok-like pan, creating their distinctive shape. While not tied to a specific festival, they''re a cherished part of daily meals and celebrations alike.');
INSERT INTO public.culture_stories VALUES (13, 18, 'Kūtai', 'https://www.learnz.org.nz/sites/learnz.org.nz/files/ss221-kohunga-kutai-01.jpg', 'New Zealand', 'A traditional Māori delicacy. A greenshell mussel native to New Zealand, prized for its flavor and cultural significance.', 'Kūtai, a traditional Māori fermented corn pudding, embodies the resourcefulness and culinary heritage of New Zealand''s indigenous culture. It is often served at cultural gatherings and celebrations, showcasing the Māori''s deep connection to their land and sustainable practices. A fun fact is that the fermentation process not only preserves the corn but also enhances its flavor and potential probiotic benefits, making it a nutritious and flavorful dish.');
INSERT INTO public.culture_stories VALUES (10, 15, 'Peking Duck', 'https://redhousespice.com/wp-content/uploads/2022/01/sliced-peking-duck-with-pancakes-scaled.jpg', 'China', 'A renowned traditional Chinese dish that is a cultural icon with a rich history.', 'Peking Duck, a dish steeped in history, originates from Beijing and was once served to emperors, symbolizing luxury and culinary excellence. It''s often enjoyed during special celebrations and state banquets, showcasing its cultural significance. Interestingly, chefs prepare the duck by pumping air under the skin to achieve its signature crispy texture, a technique that highlights the artistry behind this beloved dish.');
INSERT INTO public.culture_stories VALUES (3, 8, 'Rice and Curry', 'https://blog.kapruka.com/wp-content/uploads/2025/05/Sri-Lankan-rice-and-curry-plate-sri-lankan-cuisine-travel-1170x658-1-1024x576.jpg', 'Sri Lanka', 'A traditional dish of steamed rice served with flavorful, aromatic curries.', 'Rice and curry, a cornerstone of South Asian and Southeast Asian cuisines, symbolizes hospitality and community, often served at gatherings to foster togetherness. It''s a star dish during Sri Lanka''s Sinhala and Tamil New Year and Thailand''s Songkran festival. Interestingly, Kerala''s traditional sadya features up to 30 curries, showcasing the dish''s rich diversity and cultural depth.');
INSERT INTO public.culture_stories VALUES (14, 19, 'Kai Moana', 'https://cloudfront-ap-southeast-2.images.arcpublishing.com/nzme/Z7HPP7P7YITSZUZYBZZN6PMBYQ.jpg', 'New Zealand', 'A traditional Maori dish featuring raw seafood marinated in native flavors, celebrating the ocean''s bounty.', 'Kai Moana, a traditional raw fish dish from Polynesian cultures like Hawaiian and Maori, symbolizes the deep connection between the people and the ocean, embodying their identity and sustenance. It is often served during significant cultural celebrations, such as the Makahiki festival in Hawaii, which honors the harvest and peace. A fun fact is its preparation, typically involving fresh fish marinated in coconut milk and native herbs, highlighting traditional culinary techniques passed through generations.');
INSERT INTO public.culture_stories VALUES (6, 11, 'Dumpling', 'https://christieathome.com/wp-content/uploads/2024/04/dumpling-sauce1.jpg', 'China', 'A dough wrapper filled with ingredients such as meat, vegetables, or sweets, cooked by boiling, steaming, frying, or baking.', 'Dumplings hold a cherished place in many cultures, particularly in China, where they symbolize wealth and good fortune, especially during the Chinese New Year. Their origins trace back to Zhang Zhongjing, a Chinese doctor who created them to aid those with frostbitten ears. Beyond festivals, dumplings embody family and prosperity, with their preparation often a communal, bonding experience.');
INSERT INTO public.culture_stories VALUES (9, 14, 'Spring Rolls', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTP-lpG6vB4eiWs6TiXIxgctqh0FyWfKbmpmA&s', 'China', 'Crispy, golden pastries filled with vegetables and/or meat, symbolizing prosperity in Asian cultures', 'Spring rolls hold deep cultural significance in many Asian traditions, symbolizing wealth and new beginnings, especially during the Chinese Spring Festival. Their golden color when fried resembles gold bars, embodying prosperity. These versatile delicacies come in various fillings, from vegetables to meats, reflecting diverse cultural influences across Asia.');
INSERT INTO public.culture_stories VALUES (8, 13, 'Kung Pao Chicken', 'https://www.seriouseats.com/thmb/AaMf6tliWc3jh0R-9KLiJG5fzZo=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/__opt__aboutcom__coeus__resources__content_migration__serious_eats__seriouseats.com__2014__07__2021-02-12-Take-Out-Kung-Pao-Chicken-MHOM-11-c46f6c06713c45c5a287ddbf08779d04.jpg', 'China', 'A spicy, savory Sichuan dish featuring stir-fried chicken, peanuts, vegetables, and chili peppers, known for its bold flavors and global popularity.', 'Kung Pao Chicken, a spicy Sichuan dish named after Governor Ding Baozhen, symbolizes the region''s bold culinary spirit. While not tied to a specific festival, it''s a staple in Sichuan cuisine, often celebrated in local food festivals. Interestingly, its original name, "Gong Bao Ji Ding," translates to "Palace Guardian Chicken," and it was created in the late 19th century.');
INSERT INTO public.culture_stories VALUES (5, 10, 'Kottu Roti', 'https://media.licdn.com/dms/image/v2/D4E12AQH54QObnSWy7Q/article-cover_image-shrink_720_1280/article-cover_image-shrink_720_1280/0/1685435515459?e=2147483647&v=beta&t=bTdCgWOHCyLAUwLSVU0qtIqXroea2ULPBb2m6-QF5LA', 'Sri Lanka', 'A Sri Lankan dish made by stir-frying shredded roti with vegetables, eggs, and meat, often accompanied by a rhythmic clanging sound during preparation.', 'Kottu Roti, a beloved Sri Lankan dish, is crafted from chopped roti stir-fried with vegetables, meat, or eggs, often accompanied by chili and curry. This comfort food holds a special place in Sri Lankan culture, fostering social bonds as it''s frequently enjoyed at street stalls and family gatherings. Its name, derived from the Tamil word for "chop" or "mix," reflects its dynamic preparation. While not central to any major festival, Kottu Roti is a popular street food during various celebrations and events, highlighting its enduring appeal.');
INSERT INTO public.culture_stories VALUES (15, 20, 'Puha and Pork', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS_NnumgbggfMzaMaR5HMub_v5i5U7XBAPZBA&s', 'New Zealand', 'A traditional Māori dish featuring slow-cooked pork and puha, a native New Zealand flax root, celebrating cultural heritage through flavor.', 'Puha and Pork is a traditional Māori dish from New Zealand, made with fermented corn (puha) and pork, symbolizing resourcefulness and community. It’s often served at cultural gatherings and festivals like Matariki (Māori New Year), celebrating heritage and renewal. Fun fact: The fermentation process can take weeks, giving it a tangy flavor that’s either loved or found acquired!');
INSERT INTO public.culture_stories VALUES (1, 6, 'Konda Kavum', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ_AxAswLp9_jKAOrjl6KRH1cpq-EIjqe9EuA&s', 'Sri Lanka', 'A Sri Lankan sweet made from rice flour and coconut, steamed into cylindrical rolls.', 'Konda Kavum, a traditional Sri Lankan sweet, is a treacle-based delicacy often served at weddings and religious ceremonies, symbolizing good fortune and prosperity. It''s a popular treat during the Vesak festival, celebrating the Buddha''s birth. Interestingly, its name translates to "umbrella cake" due to its unique shape, resembling an umbrella.');
