INSERT INTO public.restaurants VALUES (556, 'y1rcbQRL619YcDmIBZodhA', 'The Hangi Shop', 'the-hangi-shop-auckland', 'https://s3-media0.fl.yelpcdn.com/bphoto/cI-hKKI1BPB5nIOr-y8Drw/o.jpg', false, 'https://www.yelp.com/biz/the-hangi-shop-auckland?adjust_creative=hldflfx6lrRiQeQId--jTw&utm_campaign=yelp_api_v3&utm_medium=api_v3_business_search&utm_source=hldflfx6lrRiQeQId--jTw', 5, 4.2, NULL, '+6492762267', '+64 9 276 2267', -36.9489099, 174.8455453, 12165.936239938224, '{"business_temp_closed": null, "menu_url": null, "waitlist_reservation": null}', 556, 'The Hangi Shop is a restaurant celebrating Māori culture through traditional earth oven-cooked cuisine, offering an authentic taste of New Zealand''s indigenous heritage with modern flair.');
INSERT INTO public.restaurants VALUES (561, 'FUWmHO-9vFeyN2829R6eRw', 'The Grand Ceylon', 'the-grand-Ceylon-sri-lanka-auckland', 'https://lh3.googleusercontent.com/p/AF1QipOhknMvHIAFEvQIL4zF6oVKnU9Acf_UVAr12-Et=s1360-w1360-h1020-rw', false, 'https://www.ordermeal.co.nz/grand-ceylon/', 50, 4.6, NULL, '+6492822155', '+64 9 282 2155', -36.9791, 174.8519, 4502.26585290502, '{"business_temp_closed": null, "menu_url": "https://www.ordermeal.co.nz/grand-ceylon/", "open24_hours": null, "waitlist_reservation": null}', 561, 'The Grand Ceylon is a restaurant that celebrates the rich culinary heritage of Sri Lanka, blending vibrant island flavors with modern elegance to create an authentic and refined dining experience.');
INSERT INTO public.restaurants VALUES (220, '7RHn5FSnPkJUgzDSCXT-Nw', 'Chamate Dining', 'chamate-dining-auckland', 'https://s3-media0.fl.yelpcdn.com/bphoto/dV6Sfw08HXMASrSQ7FjwGQ/o.jpg', false, 'https://www.yelp.com/biz/chamate-dining-auckland?adjust_creative=hldflfx6lrRiQeQId--jTw&utm_campaign=yelp_api_v3&utm_medium=api_v3_business_search&utm_source=hldflfx6lrRiQeQId--jTw', 7, 4.6, NULL, '+6493027788', '+64 9 302 7788', -36.84595, 174.76448, 1534.7264516109235, '{"business_temp_closed": null, "menu_url": null, "open24_hours": null, "waitlist_reservation": null}', 220, 'Chamate Dining is a modern restaurant celebrating the vibrant fusion of Chinese and Latin American cuisines, blending bold flavors and techniques to create a unique cultural dining experience. Our menu reflects a harmonious exchange of culinary traditions, offering a fresh and exciting take on cross-cultural cuisine.');
INSERT INTO public.restaurants VALUES (557, 'y1rcbQRL619ikomIBZodhA', 'Ahi. Restaurant', 'ahi-restaurant-auckland', 'https://lh3.googleusercontent.com/p/AF1QipMbDr_gZP17Da3Pgz-PZdDFzZJhAjmhM5lpkQjo=s1360-w1360-h1020-rw', false, 'https://ahirestaurant.co.nz/', 50, 4.6, NULL, '+64225244255', '+64 22 524 4255', -36.8436, 174.7665, 12165.936239938224, '{"business_temp_closed": null, "menu_url": "https://ahirestaurant.co.nz/menu/", "waitlist_reservation": null}', 557, 'Ahi. Restaurant offers a contemporary dining experience rooted in Pacific Rim flavors, blending traditional Hawaiian and Asian influences with fresh, locally sourced ingredients and innovative techniques.');
INSERT INTO public.restaurants VALUES (558, 'y1rcbQRL619ikomIBZodhB', 'Onemata Restaurant', 'onemata-restaurant-auckland', 'https://lh3.googleusercontent.com/p/AF1QipPvcErJdwpdN5hqJbzFQuuvEiWpt9BTJIME0lVW=w289-h312-n-k-no', false, 'https://onematarestaurant.co.nz/', 60, 4.4, NULL, '+6493662500', '+64 9 366 2500', -36.8417, 174.7587, 12165.936239938224, '{"business_temp_closed": null, "menu_url": "https://onematarestaurant.co.nz/menu/", "waitlist_reservation": null}', 558, 'Onemata Restaurant is a vibrant celebration of global culinary traditions, blending rich cultural flavors with modern gastronomic techniques to create an unforgettable dining experience.');
